#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <assert.h>

#define QUEUE_CAP 16

typedef struct {
    int data[QUEUE_CAP];
    size_t head;
    size_t tail;
    size_t count;
    bool shutdown;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} mpmc_queue_t;

void mpmc_init(mpmc_queue_t *q) {
    q->head = q->tail = q->count = 0;
    q->shutdown = false;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
}

void mpmc_destroy(mpmc_queue_t *q) {
    pthread_cond_destroy(&q->not_full);
    pthread_cond_destroy(&q->not_empty);
    pthread_mutex_destroy(&q->lock);
}

bool mpmc_push(mpmc_queue_t *q, int item) {
    pthread_mutex_lock(&q->lock);
    while (q->count == QUEUE_CAP && !q->shutdown) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    if (q->shutdown) {
        pthread_mutex_unlock(&q->lock);
        return false;
    }
    q->data[q->tail] = item;
    q->tail = (q->tail + 1) % QUEUE_CAP;
    q->count++;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
    return true;
}

bool mpmc_pop(mpmc_queue_t *q, int *out) {
    pthread_mutex_lock(&q->lock);
    while (q->count == 0 && !q->shutdown) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    if (q->count == 0 && q->shutdown) {
        pthread_mutex_unlock(&q->lock);
        return false;
    }
    *out = q->data[q->head];
    q->head = (q->head + 1) % QUEUE_CAP;
    q->count--;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return true;
}

void mpmc_close(mpmc_queue_t *q) {
    pthread_mutex_lock(&q->lock);
    q->shutdown = true;
    pthread_cond_broadcast(&q->not_empty);
    pthread_cond_broadcast(&q->not_full);
    pthread_mutex_unlock(&q->lock);
}

typedef struct {
    mpmc_queue_t *q;
    long long sum;
} consumer_arg_t;

void *producer_fn(void *arg) {
    mpmc_queue_t *q = (mpmc_queue_t *)arg;
    for (int i = 1; i <= 50; i++) {
        mpmc_push(q, i);
    }
    return NULL;
}

void *consumer_fn(void *arg) {
    consumer_arg_t *carg = (consumer_arg_t *)arg;
    int val;
    while (mpmc_pop(carg->q, &val)) {
        carg->sum += val;
    }
    return NULL;
}

int main(void) {
    mpmc_queue_t q;
    mpmc_init(&q);

    pthread_t prod, cons;
    consumer_arg_t carg = { .q = &q, .sum = 0 };

    pthread_create(&cons, NULL, consumer_fn, &carg);
    pthread_create(&prod, NULL, producer_fn, &q);

    pthread_join(prod, NULL);
    mpmc_close(&q);
    pthread_join(cons, NULL);

    // Sum of 1..50 = (50 * 51) / 2 = 1275
    assert(carg.sum == 1275);
    mpmc_destroy(&q);
    printf("C SFT 0004: MPMC queue test passed. Sum = %lld\n", carg.sum);
    return 0;
}

