#include <iostream>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <optional>
#include <thread>
#include <vector>
#include <cassert>

template <typename T>
class BoundedBlockingQueue {
public:
    explicit BoundedBlockingQueue(size_t capacity)
        : capacity_(capacity), shutdown_(false) {
        assert(capacity > 0);
    }

    ~BoundedBlockingQueue() {
        close();
    }

    bool push(T item) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this]() { return queue_.size() < capacity_ || shutdown_; });
        if (shutdown_) return false;
        queue_.push(std::move(item));
        not_empty_.notify_one();
        return true;
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this]() { return !queue_.empty() || shutdown_; });
        if (queue_.empty() && shutdown_) return std::nullopt;
        T item = std::move(queue_.front());
        queue_.pop();
        not_full_.notify_one();
        return item;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            shutdown_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.size();
    }

private:
    const size_t capacity_;
    std::queue<T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    bool shutdown_;
};

int main() {
    BoundedBlockingQueue<int> q(5);
    long long total_consumed = 0;

    std::thread consumer([&q, &total_consumed]() {
        while (auto val = q.pop()) {
            total_consumed += *val;
        }
    });

    std::thread producer([&q]() {
        for (int i = 1; i <= 50; ++i) {
            bool ok = q.push(i);
            assert(ok);
        }
        q.close();
    });

    producer.join();
    consumer.join();

    // 1 + 2 + ... + 50 = (50 * 51) / 2 = 1275
    assert(total_consumed == 1275);
    assert(q.size() == 0);

    std::cout << "CPP SFT 0001: BoundedBlockingQueue tests passed. Total: " << total_consumed << "\n";
    return 0;
}

