        int expected = (static_cast<int>(i) + 1) * (static_cast<int>(i) + 1);
        assert(val == expected);
        total += val;
    }

    // Sum of squares 1..20 = (20 * 21 * 41) / 6 = 2870
    assert(total == 2870);
