    assert_eq!(five.strong_count(), 2);
    assert_eq!(*five_clone, 5);

    drop(five_clone);
    assert_eq!(five.strong_count(), 1);

    println!("RUST SFT 0005: Custom SimpleArc memory model and deallocation verified.");
}

