	"fmt"
	"sync"
	"time"
)

type Result struct {
	Input  int
	Output int
	Err    error
}

func WorkerPool(ctx context.Context, numWorkers int, jobs []int) []Result {
	jobsChan := make(chan int, len(jobs))
	resultsChan := make(chan Result, len(jobs))

	for _, j := range jobs {
		jobsChan <- j
	}
	close(jobsChan)

	var wg sync.WaitGroup
	for w := 0; w < numWorkers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case job, ok := <-jobsChan:
					if !ok {
						return
					}
					// Simulate work
					resultsChan <- Result{
						Input:  job,
						Output: job * 2,
						Err:    nil,
					}
				}
			}
		}()
	}

	wg.Wait()
	close(resultsChan)

	var results []Result
	for res := range resultsChan {
		results = append(results, res)
	}
	return results
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	inputs := make([]int, 20)
	for i := 0; i < 20; i++ {
		inputs[i] = i + 1
	}

	results := WorkerPool(ctx, 4, inputs)
	if len(results) != 20 {
		panic(fmt.Sprintf("Expected 20 results, got %d", len(results)))
	}

	sum := 0
	for _, r := range results {
		sum += r.Output
	}

	// Sum 1..20 * 2 = 2 * (20 * 21) / 2 = 420
	if sum != 420 {
		panic(fmt.Sprintf("Expected sum 420, got %d", sum))
	}

	fmt.Printf("GO SFT 0001: WorkerPool executed cleanly. Sum = %d\n", sum)
}

